<?php require __DIR__.'/app/layout.php';$user=must_login();
$rows=all_rows('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 200',[$user['id']]);
page_start('Notifications','notices');titlebar('Centre de notifications','Notifications','Évènements liés à vos réservations.'); ?>
<div class="panel"><div class="panel-head"><h3>Dernières notifications</h3><div class="d-flex gap-2"><?php if(is_admin()):?><form method="post" action="<?=h(url('actions.php'))?>"><?=csrf_field()?><input type="hidden" name="action" value="reminders_send"><button class="btn btn-outline-primary btn-sm">Générer rappels 24 h</button></form><?php endif;?><form method="post" action="<?=h(url('actions.php'))?>"><?=csrf_field()?><input type="hidden" name="action" value="notice_read"><input type="hidden" name="all" value="1"><button class="btn btn-outline-secondary btn-sm">Tout marquer comme lu</button></form></div></div>
<?php foreach($rows as $r):?><div class="d-flex align-items-center gap-3 py-3 border-bottom"><span class="stat-icon position-static flex-shrink-0" style="width:37px;height:37px"><i class="bi bi-bell"></i></span><div class="flex-grow-1"><div class="<?= !$r['is_read']?'fw-bold':'' ?>"><?=h($r['message'])?></div><small class="muted"><?=h($r['created_at'])?></small></div><?php if(!$r['is_read']):?><form method="post" action="<?=h(url('actions.php'))?>"><?=csrf_field()?><input type="hidden" name="action" value="notice_read"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn btn-sm btn-outline-secondary">Marquer comme lu</button></form><?php endif;?></div><?php endforeach;?><?php if(!$rows):?><div class="empty-state"><i class="bi bi-bell-slash"></i>Aucune notification pour le moment.</div><?php endif;?></div>
<?php page_end();?>
